 public static void Run(){int exit=0;string output=Path.Combine(Root,"Evidence119Baseline");Directory.CreateDirectory(output);try{EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var rp=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>("Assets/Settings/PC_RPAsset.asset");GraphicsSettings.defaultRenderPipeline=rp;QualitySettings.renderPipeline=rp;var folder="Assets/Grounded119-before";if(AssetDatabase.IsValidFolder(folder))throw new Exception("fresh output required");AssetDatabase.CreateFolder("Assets","Grounded119-before");var root=new GameObject("formal grounded shells");int n=GroundedBefore119.Build(Path.Combine(Root,"Input119"),folder,root.transform,Shader.Find("MapSharedProps/Lit"));if(n!=1)throw new Exception("formal placed shell");var o=root.transform.GetChild(0).gameObject;var material=o.GetComponent<Renderer>().sharedMaterial;if(material.IsKeywordEnabled("SMALL_PROP_LOCAL_LIGHTS"))throw new Exception("assumption wrong: already enabled");PrefabUtility.SaveAsPrefabAsset(o,"Assets/grounded119-before.prefab");AssetDatabase.SaveAssets();RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=Color.black;RenderSettings.ambientIntensity=0;RenderSettings.skybox=null;RenderSettings.reflectionIntensity=0;
